<script setup>
import FriendlyIcon from './FriendlyIcon.vue'
import { displayDate, displayLunar } from './calendarPresentation.js'
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { agricultureAssetContentUrl } from './api.js'
const p=defineProps(['garden','overview','live','metrics','tasks','workspaceId','observations','error','uncertain','pending'])
defineEmits(['task','navigate','report','reconcile','retry','explain'])
const root=ref(null), chartMetric=ref('')
const page=ref('garden'), weatherOpen=ref(false), clock=ref(Date.now())
watch(page,async()=>{await nextTick();root.value?.closest('main')?.scrollTo({top:0})})
const due=t=>{const value=t?.dueAt || t?.due_at || t?.dueDate;return value ? new Date(typeof value==='number'?value*1000:value).toLocaleDateString('zh-CN') : '未设时间'}
const week=computed(()=>{const value=p.overview?.presentation?.calendar?.date;if(!value || displayDate(value)==='日期暂不可用') return [];const date=new Date(`${value}T12:00:00+08:00`);const weekday=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'Asia/Shanghai'}).format(date));return ['一','二','三','四','五','六','日'].map((label,index)=>{const d=new Date(date.getTime()+(index-weekday)*86400000);return {label,day:new Intl.DateTimeFormat('zh-CN',{day:'numeric',timeZone:'Asia/Shanghai'}).format(d),selected:index===weekday}})})
const almanac=computed(()=>p.overview?.presentation?.calendar || {})
const nodes=computed(()=>almanac.value.status==='available' ? almanac.value.nodes || [] : [])
const nextFestival=computed(()=>nodes.value.find(node=>node.type==='lunarFestival'))
const nodeTiming=node=>node.daysUntil===0 ? '今天' : `还剩${node.daysUntil}天`
const weatherIcon=condition=>/雨/.test(condition||'')?'rain':'weather'
const chart=computed(()=>readings.value.find(m=>m.metric===chartMetric.value)||readings.value[0])
const chartValues=computed(()=>(p.live?.enabled?p.live.samples||[]:(p.observations||[]).filter(x=>x.metric===chart.value?.metric).map(x=>({...x,[x.metric]:x.value}))).slice(-12))
let timer
onMounted(()=>{timer=setInterval(()=>clock.value=Date.now(),1000)})
onBeforeUnmount(()=>clearInterval(timer))
const updated=computed(()=>p.live?.enabled ? p.live.samples?.at(-1)?.observedAt : p.observations?.at(-1)?.observedAt)
const time=value=>value ? new Date(typeof value==='number'?value*1000:value).toLocaleTimeString('zh-CN', {hour:'2-digit',minute:'2-digit',hour12:false}) : '暂无观测'
const stale=computed(()=>p.live?.enabled && (p.live.status==='stale' || !updated.value || clock.value-Number(updated.value)*1000>(p.live.staleAfterSeconds || 20)*1000))
const alertCount=computed(()=>p.overview?.alerts?.filter(x=>x.status==='open').length || 0)
const photo=computed(()=>p.live?.enabled ? p.live.cameras?.find(x=>x.assetId)?.assetId : p.overview?.assets?.find(x=>x.kind==='image')?.id)
const readings=computed(()=>p.metrics.map(x=>({...x,value:p.live?.enabled ? p.live.samples?.at(-1)?.[x.metric] : x.reading?.value})))
function trend(metric) {
 const values = (p.live?.enabled ? p.live.samples || [] : (p.observations || []).filter(x => x.metric === metric).map(x => ({[metric]: x.value}))).slice(-12).filter(x => x[metric] != null).map(x => Number(x[metric])).filter(Number.isFinite)
 if(values.length < 2) return ''
 const low=Math.min(...values), range=Math.max(...values)-low || 1
 return values.map((value,index)=>`${index*90/(values.length-1)},${22-(value-low)*18/range}`).join(' ')
}
</script>
<template><section ref="root" class="garden-fidelity" :class="{'garden-subpage':page!=='garden'}">
<template v-if="page==='garden'">
<h2>今天，先看这两件事</h2>
<article v-if="tasks[0]" class="priority"><div class="priority-content"><div class="task-illustration"><span>园区示意</span></div><div><small class="pill">待处理</small><h3>{{ tasks[0].title }}</h3><p>{{ (tasks[0].description || '查看任务详情').replace(/\*\*/g,'').split('\n')[0] }}</p><small>◷ {{ due(tasks[0]) }}</small></div></div><button class="primary" @click="$emit('task',tasks[0].id)">去看看　 →</button></article>
<button v-if="tasks[1]" class="secondary-task" @click="$emit('task',tasks[1].id)"><span class="task-icon"><i class="bi bi-clipboard-check" aria-hidden="true"></i></span><div><strong>{{ tasks[1].title }}</strong><small>查看最新记录，确认是否异常</small></div>›</button><p v-if="!tasks.length">暂无待办，园区变化随时记录。</p>
<div class="section-heading"><h2>园里此刻</h2><button @click="$emit('navigate','monitor')">查看现场 ›</button></div>
<article class="field-card"><div class="field-photo"><img v-if="photo" :src="agricultureAssetContentUrl(workspaceId,photo)" alt="园区已授权画面"><div v-else class="placeholder">暂无现场画面</div><small>{{ live?.enabled ? '模拟画面' : '人工上传' }}</small></div><button class="readings-button" @click="page='readings'"><small>{{ live?.enabled ? '模拟观测' : '监测记录' }} · 更新于 {{ time(updated) }}</small><div class="reading-grid"><div v-for="m in readings.slice(0,3)" :key="m.metric"><strong>{{ m.value == null ? '—' : `${Number(m.value).toFixed(1)}${m.unit}` }}</strong><small>{{ m.label }}</small></div></div></button></article>
<div class="shortcuts"><button @click="$emit('navigate','monitor')"><i class="bi bi-camera" aria-hidden="true"></i> 监控</button><button @click="$emit('navigate','devices')"><i class="bi bi-grid" aria-hidden="true"></i> 设备</button><button @click="$emit('report')"><i class="bi bi-journal-text" aria-hidden="true"></i> 报告</button></div>
<button class="weather-entry" @click="page='weather'"><span aria-hidden="true">☀</span><span><strong>黄历与天气</strong><small>{{ displayLunar(almanac.lunarDate) }}</small><span v-if="nodes[0]" class="entry-reminder">{{ nodes[0].name }} · {{ nodeTiming(nodes[0]) }}</span></span><span aria-hidden="true">›</span></button>
</template>
<template v-else><button class="back" @click="page='garden'">‹ 返回园区</button><h2>{{ page==='readings' ? '现场读数' : '黄历与天气' }}</h2>
<template v-if="page==='readings'"><div class="large-readings"><article v-for="m in readings.slice(0,2)" :key="m.metric"><span><i :class="['bi', m.metric==='temperature' ? 'bi-thermometer-half' : 'bi-droplet']" aria-hidden="true"></i> {{ m.label }}</span><strong>{{ m.value == null ? '—' : `${Number(m.value).toFixed(1)}${m.unit}` }}</strong></article></div><article class="trend-card"><h3>最近趋势</h3><div class="chart-tabs"><button v-for="m in readings.slice(0,2)" :key="m.metric" :aria-pressed="chart?.metric===m.metric" @click="chartMetric=m.metric">{{ m.label }}</button></div><div v-if="chart" class="axis-chart"><div class="y-ticks"><small>{{ Math.max(...chartValues.map(x=>Number(x[chart.metric])).filter(Number.isFinite),0).toFixed(1) }}</small><small>{{ (chartValues.length ? Math.min(...chartValues.map(x=>Number(x[chart.metric])).filter(Number.isFinite)) : 0).toFixed(1) }}</small></div><svg viewBox="0 0 90 26" :aria-label="chart.label+'近期趋势'"><path d="M0 0V25H90" fill="none" stroke="#cbd7ce"/><polyline :points="trend(chart.metric)" fill="none" stroke="#165442"/></svg><div class="x-ticks"><small>{{ time(chartValues[0]?.observedAt) }}</small><small>{{ time(chartValues.at(-1)?.observedAt) }}</small></div></div><p>观测时间 {{ time(updated) }}</p><small>来源：{{ live?.enabled ? '模拟传感器' : '园区监测记录' }}</small></article><article class="priority"><h3>⚠ 先核对现场</h3><p>读数需结合观测时间与现场核查；模拟数据仅供演示。</p><button class="primary" @click="$emit('explain','请解释当前园区这组数据，区分已知事实与待现场核实事项。')">问问这组数据</button></article></template>
<template v-else><article class="trend-card"><h3>{{ displayDate(overview?.presentation?.calendar?.date) }}</h3><p>{{ displayLunar(overview?.presentation?.calendar?.lunarDate) }}</p><div v-if="week.length" class="week-strip"><div v-for="day in week" :key="day.label"><small>{{ day.label }}</small><strong :class="{today:day.selected}">{{ day.day }}</strong></div></div></article><article class="trend-card almanac-card"><h3>今日黄历</h3><template v-if="almanac.status==='available'"><p>{{ almanac.jieQi ? '今日 · '+almanac.jieQi : almanac.season+'时节' }} · 下一节气 {{ almanac.nextJieQi }}</p><div class="almanac-row"><strong>宜</strong><span>{{ (almanac.yi || []).slice(0,3).join(' · ') || '暂无' }}</span></div><div class="almanac-row avoid"><strong>忌</strong><span>{{ (almanac.ji || []).slice(0,3).join(' · ') || '暂无' }}</span></div><details><summary>查看完整宜忌</summary><p>宜：{{ (almanac.yi || []).join(' · ') || '暂无' }}</p><p>忌：{{ (almanac.ji || []).join(' · ') || '暂无' }}</p></details></template><p v-else>黄历暂不可用，请稍后刷新核对。</p><small>传统文化参考，农事安排请结合现场与当地天气。</small></article><article class="trend-card"><h3>节气与农历提醒</h3><p v-if="nextFestival" class="festival-summary">{{ nextFestival.daysUntil===0 ? '今天的农历节日' : '下个农历节日' }}：{{ nextFestival.name }} · {{ nodeTiming(nextFestival) }}</p><p v-if="!nodes.length">提醒暂不可用</p><div v-for="node in nodes.slice(0,4)" :key="node.id" class="calendar-node"><div><strong>{{ node.name }}</strong><span>{{ nodeTiming(node) }}</span></div><small>{{ node.date.replaceAll('-','/') }} · {{ displayLunar(node.lunarDate) }}</small></div><details v-if="nodes.length>4"><summary>查看未来一年</summary><div v-for="node in nodes.slice(4)" :key="node.id" class="calendar-node"><div><strong>{{ node.name }}</strong><span>{{ nodeTiming(node) }}</span></div><small>{{ node.date.replaceAll('-','/') }} · {{ displayLunar(node.lunarDate) }}</small></div></details></article><article class="trend-card"><small>园区天气 · 天气示例</small><div class="weather-big"><FriendlyIcon :name="weatherIcon(overview?.presentation?.weather?.condition)"/><strong>{{ overview?.presentation?.weather?.temperature ?? '—' }}°C</strong></div><h3>{{ overview?.presentation?.weather?.condition || '暂无天气' }}</h3><div class="forecast"><div v-for="day in overview?.presentation?.weather?.forecast || []" :key="day.label"><strong>{{ day.label }}</strong><FriendlyIcon :name="weatherIcon(day.condition)"/><p>{{ day.condition }}</p></div></div></article><article class="priority"><h3>出门前，再核对当地天气</h3><p>天气为演示样例，请在出发前确认实际天气。</p></article><button class="primary" @click="page='garden'">回到园区</button></template></template>
<p v-if="error || uncertain || stale || live?.paused || live?.status==='disconnected'" role="status">{{ error || (uncertain ? '操作结果尚未确认' : '数据暂不可用，请刷新核对') }} <button :disabled="pending" @click="$emit('reconcile')">刷新核对</button><button v-if="uncertain" :disabled="pending" @click="$emit('retry')">重试原请求</button></p>
</section></template>
<style scoped>
.weather-entry{display:grid;grid-template-columns:24px minmax(0,1fr) 14px;align-items:center;gap:8px}.entry-reminder{display:block;font-size:16px;margin-top:6px}.weather-entry small{display:block;margin-top:4px}.almanac-row{display:flex;gap:12px;margin:14px 0;font-size:18px;line-height:1.6}.almanac-row strong{color:#267452}.almanac-row.avoid strong{color:#936347}.almanac-row span{min-width:0;overflow-wrap:anywhere}.almanac-card{background:#fbfaf3}.garden-fidelity details{margin:12px 0}.garden-fidelity summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-size:16px;color:#165442}.calendar-node{padding:14px 0;border-bottom:1px solid #edf1ec;overflow-wrap:anywhere}.calendar-node>div{display:flex;justify-content:space-between;gap:10px;font-size:18px}.calendar-node>div span{font-size:15px;flex-shrink:0}.calendar-node small{display:block;margin-top:7px;line-height:1.6}.festival-summary{background:#f0f6eb;border-radius:10px;padding:10px}

.garden-fidelity{color:#123c32;display:grid;gap:12px}.garden-fidelity h2{font-size:22px;margin:8px 0 0}.garden-fidelity h3{font-size:18px;margin:7px 0}.garden-fidelity p{font-size:16px;margin:8px 0;line-height:1.5}.garden-fidelity small{font-size:13px;color:#64756e}.garden-fidelity button{cursor:pointer;font:inherit;min-height:44px;border:1px solid #e7ece7;background:white;border-radius:12px;color:inherit}.priority{padding:12px;border:1px solid #ffe3a1;border-radius:16px;background:#fff5de}.priority-content{display:flex;gap:12px}.priority-content>div:last-child{flex:1;min-width:0}.priority-content p{max-height:48px;overflow:hidden}.task-illustration{width:100px;height:100px;flex-shrink:0;border-radius:12px;background:url('/friendly/covers-grid-v1.png') 0 0/300% 200%;display:flex;align-items:end}.task-illustration span{font-size:11px;background:#ffffffdc;padding:3px}.pill{background:#ffdb8e;padding:4px 12px;border-radius:20px}.garden-fidelity .primary{background:#165442;color:white;min-height:50px;width:100%;margin-top:10px;border:0;font-weight:700}.secondary-task{display:flex;align-items:center;text-align:left;gap:12px;padding:12px}.secondary-task small{display:block;margin-top:5px}.section-heading{display:flex;align-items:center;justify-content:space-between;margin-top:8px}.section-heading button{border:0;background:transparent}.field-card,.trend-card{border:1px solid #e7ece7;border-radius:16px;overflow:hidden;background:white}.field-photo{height:130px;position:relative;background:#e6f5dd}.field-photo img{width:100%;height:100%;object-fit:cover}.field-photo>small{position:absolute;right:8px;top:8px;background:#ffffffd9;border-radius:8px;padding:4px}.placeholder{height:100%;display:grid;place-items:center}.readings-button{width:100%;padding:10px;border:0!important}.reading-grid{display:grid;grid-template-columns:repeat(3,1fr);margin-top:12px}.reading-grid strong,.reading-grid small{display:block}.reading-grid strong{font-size:20px}.reading-grid>div+div{border-left:1px solid #e7ece7}.shortcuts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.weather-entry{text-align:left;padding:8px 12px}.back{justify-self:start;border:0!important}.large-readings{display:grid;grid-template-columns:1fr 1fr;gap:12px}.large-readings article{background:#f3f9f1;border-radius:16px;padding:18px}.large-readings strong{display:block;font-size:36px;margin-top:18px}.trend-card{padding:16px}.trend-card svg{width:100%;height:100px}.weather-big{font-size:48px;margin:20px 0}.forecast{display:flex;justify-content:space-around;margin-top:24px}
.agri-main .garden-fidelity button{font-size:16px}.agri-main .garden-fidelity .primary{font-size:17px;font-weight:600}.agri-main .garden-fidelity .priority-content h3{font-size:18px}.agri-main .garden-fidelity .priority-content p{font-size:15px}.agri-main .garden-fidelity .secondary-task strong{font-size:18px}.agri-main .garden-fidelity .secondary-task small{font-size:14px}.task-icon{width:40px;height:40px;display:grid;place-items:center;border-radius:12px;background:#edf6e9;font-size:24px;flex-shrink:0}.agri-main .garden-fidelity .shortcuts button{display:flex;align-items:center;justify-content:center;gap:8px;font-size:14px}.shortcuts i{font-size:24px}.agri-main .garden-fidelity .large-readings strong{font-size:36px}.large-readings i{font-size:24px}.chart-tabs{display:flex;gap:8px}.chart-tabs button{padding:0 12px}.chart-tabs button[aria-pressed=true]{background:#e6f5dd}.axis-chart{display:grid;grid-template-columns:35px 1fr;margin-top:12px}.y-ticks{display:flex;flex-direction:column;justify-content:space-between}.axis-chart svg{height:100px}.x-ticks{grid-column:2;display:flex;justify-content:space-between}.trend-card .x-ticks small{font-size:11px}
.garden-fidelity{display:none}@media(max-width:767px){.garden-fidelity{display:grid;min-width:0}.week-strip{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:18px;text-align:center}.week-strip strong{width:36px;height:36px;display:grid;place-items:center;border-radius:50%;font-size:16px;margin:8px auto}.week-strip strong.today{background:#165442;color:white}.weather-big{display:flex;align-items:center;gap:16px}.weather-big :deep(.friendly-icon){width:110px;height:110px;flex-shrink:0}.weather-big strong{font-size:42px}.forecast>div{display:flex;flex-direction:column;align-items:center;flex:1}.forecast :deep(.friendly-icon){width:54px;height:54px;margin:10px 0}.forecast p{font-size:14px}.forecast>div+div{border-left:1px solid #edf1ec}}
</style>
